<body>
    <h1>2048</h1>

    <div id="game-container">
        <div id="score-board">
            <div class="score-panel">Score</div>
            <div id="score" class="score-panel">0</div>
        </div>

        <div id="board">
            <!-- Tiles will be generated here by JavaScript -->
        </div>
    </div>

    <button id="reset">New Game</button>

    <script>
/**
 * Global state variables for the game.
 */
let BOARD = [];
let SCORE = 0;
const SIZE = 4;

// --- DOM Elements ---
const boardElement = document.getElementById('board');
const scoreElement = document.getElementById('score');
const resetBtn = document.getElementById('reset');

/**
 * Initializes the game state and starts the rendering process.
 */
function initializeGame() {
    BOARD = Array(SIZE).fill(0).map(() => Array(SIZE).fill(0));
    SCORE = 0;
    drawBoard();
    updateScoreDisplay();
    addRandomTile(); // Start with 2 tiles, but we call this helper to ensure the setup matches rules.
}

/**
 * Updates the score display element on the screen.
 */
function updateScoreDisplay() {
    scoreElement.textContent = SCORE;
}

/**
 * Clears and rebuilds the board DOM representation based on the current BOARD state array.
 * This is crucial for redrawing tiles correctly after moves/spawns.
 */
function drawBoard() {
    // Clear existing tiles
    boardElement.innerHTML = ''; 

    for (let r = 0; r < SIZE; r++) {
        for (let c = 0; c < SIZE; c++) {
            const value = BOARD[r][c];
            if (value === 0) continue;

            const tile = document.createElement('div');
            tile.classList.add('tile');
            tile.setAttribute('data-value', value);
            tile.textContent = value;
            boardElement.appendChild(tile);
        }
    }
}

/**
 * Helper function to find all empty cells (0s).
 * @returns {Array<{r: number, c: number}>} List of empty cell coordinates.
 */
function findEmptyCells() {
    const empty = [];
    for (let r = 0; r < SIZE; r++) {
        for (let c = 0; c < SIZE; c++) {
            if (BOARD[r][c] === 0) {
                empty.push({ r: r, c: c });
            }
        }
    }
    return empty;
}

/**
 * Adds a new tile (2 or 4) to a random empty spot on the board.
 */
function addRandomTile() {
    const emptyCells = findEmptyCells();
    if (emptyCells.length === 0) return false; // Board is full

    // Select a random empty cell
    const randomIndex = Math.floor(Math.random() * emptyCells.length);
    const coords = emptyCells[randomIndex];

    // Determine tile value: 90% chance of 2, 10% chance of 4
    let newValue;
    if (Math.random() < 0.9) {
        newValue = 2;
    } else {
        newValue = 4;
    }

    BOARD[coords.r][coords.c] = newValue;
    drawBoard();
    return true;
}


/**
 * Core logic for processing a single line (row or column).
 * @param {Array<number>} line - The array of values (e.g., [2, 0, 2, 4]).
 * @returns {{new_line: Array<number>, score_increase: number, moved: boolean}} Result object.
 */
function processLine(line) {
    let merged = false;
    let newScore = 0;
    let newLine = [];

    // Step 1: Filter out zeros and compress (e.g., [2, 0, 2, 4] -> [2, 2, 4])
    const filteredLine = line.filter(val => val !== 0);

    if (filteredLine.length === 0) {
        return { newLine: Array(SIZE).fill(0), scoreIncrease: 0, moved: false };
    }

    // Step 2: Process merges and compress again
    let i = 0;
    while (i < filteredLine.length) {
        let val = filteredLine[i];
        let nextVal = filteredLine[i + 1];

        if (nextVal !== undefined && val === nextVal) {
            // Merge occurs!
            const mergedValue = val * 2;
            newLine.push(mergedValue);
            newScore += mergedValue;
            i += 2; // Skip the next element as it was merged
            merged = true;
        } else {
            // No merge, just slide
            newLine.push(val);
            i += 1;
        }
    }

    // Step 3: Pad with zeros to maintain size
    while (newLine.length < SIZE) {
        newLine.push(0);
    }

    const moved = JSON.stringify(line).replace(/(\d)/g, '$& ') !== JSON.stringify(newLine).replace(/(\d)/g, '$& ');


    return { newLine: newLine, scoreIncrease: newScore, moved };
}


/**
 * Applies the move logic for a specific direction (left/right or up/down).
 * @param {'up'|'down'|'left'|'right'} direction - The direction of the slide.
 * @returns {{didMove: boolean, scoreIncrease: number}} Result containing movement status and score update.
 */
function executeMove(direction) {
    let boardCopy = JSON.parse(JSON.stringify(BOARD)); // Use a copy for temporary calculations
    let newBoard = Array(SIZE).fill(0).map(() => Array(SIZE).fill(0));
    let totalScoreIncrease = 0;
    let moveMade = false;

    // Iterate through rows (if horizontal) or columns (if vertical)
    for (let i = 0; i < SIZE; i++) {
        let line = [];
        const linesToProcess = [];

        if (direction === 'left' || direction === 'right') {
            // Processing a Row: [i][c]
            for (let j = 0; j < SIZE; j++) {
                line.push(boardCopy[i][j]);
            }
            linesToProcess.push({ originalLine: line, index: i });

        } else if (direction === 'up' || direction === 'down') {
            // Processing a Column: [r][i]
            for (let j = 0; j < SIZE; j++) {
                line.push(boardCopy[j][i]);
            }
            linesToProcess.push({ originalLine: line, index: i }); // Index here represents the column 'i'

        } else {
            return { didMove: false, scoreIncrease: 0 };
        }


        // Process the line (row or col)
        const result = processLine(linesToProcess[0].originalLine);
        const newLineArray = result.newLine;

        if (!moveMade && result.scoreIncrease > 0) {
             totalScoreIncrease += result.scoreIncrease;
             moveMade = true;
        }

        // Place the processed line back onto the new board structure
        if (direction === 'left' || direction === 'right') {
            for (let j = 0; j < SIZE; j++) {
                newBoard[i][j] = newLineArray[j];
            }
        } else if (direction === 'up' || direction === 'down') {
            // If processing column 'i', we set newBoard[r][i] for r=0 to 3
            for (let j = 0; j < SIZE; j++) {
                newBoard[j][i] = newLineArray[j];
            }
        }
    }

    // Check if the overall board state changed
    const boardChanged = JSON.stringify(BOARD).replace(/(\d)/g, '$& ') !== JSON.stringify(newBoard).replace(/(\d)/g, '$& ');


    if (boardChanged) {
        BOARD = newBoard;
        drawBoard(); // Redraw the entire board with the new state
        SCORE += totalScoreIncrease;
        updateScoreDisplay();
        return { didMove: true, scoreIncrease: totalScoreIncrease };
    } else {
        // Nothing moved or merged
        return { didMove: false, scoreIncrease: 0 };
    }
}

/**
 * Public API method to handle tile movement.
 * @param {'left'|'right'|'up'|'down'} direction - The direction specified by the user input.
 * @returns {boolean} True if anything moved, false otherwise.
 */
function moveGame(direction) {
    const result = executeMove(direction);

    let didChange = result.didMove;

    // If a change happened, spawn a new tile
    if (didChange) {
        addRandomTile(); 
    }

    return didChange;
}


// =========================================
// PUBLIC API IMPLEMENTATION
// =========================================

window.game = {
  size: SIZE,

  /**
   * Resets the game state to two tiles and score 0.
   */
  reset: function() {
    initializeGame();
  },

  /**
   * Attempts a move in the given direction.
   * @param {'left'|'right'|'up'|'down'} direction 
   * @returns {boolean} True if any tiles moved or merged, false otherwise.
   */
  move: function(direction) {
    return moveGame(direction);
  },

  /**
   * Returns a copy of the current board state (4x4 array).
   * @returns {Array<Array<number>>} The 4x4 grid.
   */
  board: function() {
    // Return a deep copy to prevent external mutation
    return JSON.parse(JSON.stringify(BOARD));
  },

  /**
   * Sets the internal board state exactly, bypassing standard movement logic (for grading).
   * @param {Array<Array<number>>} arr - The 4x4 grid array.
   */
  setBoard: function(arr) {
    if (arr && arr.length === SIZE && arr[0].length === SIZE) {
        BOARD = JSON.parse(JSON.stringify(arr));
        drawBoard();
    } else {
        console.error("Invalid board array provided.");
    }
  },

  /**
   * Returns the current score.
   * @returns {number} The total accumulated score.
   */
  score: function() {
    return SCORE;
  }
};


// =========================================
// EVENT LISTENERS & INITIALIZATION
// =========================================

// 1. Keyboard Control
document.addEventListener('keydown', (event) => {
    let direction = null;
    switch (event.key) {
        case 'ArrowLeft':
            direction = 'left';
            break;
        case 'ArrowRight':
            direction = 'right';
            break;
        case 'ArrowUp':
            direction = 'up';
            break;
        case 'ArrowDown':
            direction = 'down';
            break;
        default:
            return;
    }

    event.preventDefault(); // Prevent scrolling the page

    // Execute move and handle subsequent tile spawn if successful
    const moved = window.game.move(direction);
});


// 2. Button Control
resetBtn.addEventListener('click', () => {
    window.game.reset();
});

// Start the game when the script loads
window.onload = initializeGame;
    </script>
</body>
